/**
 * Logosphere BITS — public Supabase env transfer (no dependencies).
 *
 * React Native does not read `.env` by itself, so this script copies ONLY
 * the two public mobile values (project address + anon key) from the
 * Git-ignored `.env` into the Git-ignored generated module
 * `src/config/cfgSupabaseEnv.ts`, which the app imports normally.
 *
 * Runs automatically before `npm start` (prestart) and `npm run android`
 * (preandroid). Direct Gradle builds reuse the last generated file, so
 * re-run `npm run gen:env` after changing `.env`.
 *
 * Safety: server secrets (service-role, Muse API) are never read here;
 * values are never printed and never committed (see .gitignore).
 * Failures name ONLY the missing variable.
 */

const fs = require('fs');
const path = require('path');

const projectRoot = path.join(__dirname, '..');
const envPath = path.join(projectRoot, '.env');
const outPath = path.join(projectRoot, 'src', 'config', 'cfgSupabaseEnv.ts');

const NAMES = ['SUPABASE_PROJECT_ADDRESS', 'SUPABASE_ANON_KEY'];

function readEnvFile() {
  let text;
  try {
    text = fs.readFileSync(envPath, 'utf8');
  } catch (error) {
    throw new Error(
      `Logosphere BITS: .env file is missing at ${envPath}. ` +
        'Copy .env.example to .env and fill the two public values. ' +
        `(${error.code || 'read failed'})`,
    );
  }
  const values = {};
  for (const rawLine of text.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (line === '' || line.startsWith('#')) {
      continue;
    }
    const cut = line.indexOf('=');
    if (cut < 1) {
      continue;
    }
    const name = line.slice(0, cut).trim();
    if (!NAMES.includes(name)) {
      continue;
    }
    let value = line.slice(cut + 1).trim();
    if (value.length >= 2 && value.startsWith('"') && value.endsWith('"')) {
      value = value.slice(1, -1);
    }
    values[name] = value;
  }
  for (const name of NAMES) {
    if (!values[name]) {
      throw new Error(
        `Logosphere BITS: ${name} is missing or blank in .env. ` +
          'Set it in the Git-ignored .env file (see .env.example). ' +
          'Values are never logged.',
      );
    }
  }
  return values;
}

function toSingleQuoted(value) {
  return (
    "'" +
    value
      .replace(/\\/g, '\\\\')
      .replace(/'/g, "\\'")
      .replace(/\r/g, '\\r')
      .replace(/\n/g, '\\n') +
    "'"
  );
}

function main() {
  const values = readEnvFile();
  const body = `/**
 * GENERATED by tools/gen-supabase-env.js from the Git-ignored .env.
 * Do not edit by hand; do not commit. Public mobile values only.
 */

export const fldStrSupabaseProjectAddress = ${toSingleQuoted(
    values.SUPABASE_PROJECT_ADDRESS,
  )};
export const fldStrSupabaseAnonKey = ${toSingleQuoted(
    values.SUPABASE_ANON_KEY,
  )};
`;
  fs.writeFileSync(outPath, body, 'utf8');
  console.log(
    `gen-supabase-env: wrote ${path.relative(projectRoot, outPath)} ` +
      `(${NAMES.join(', ')}; values never printed).`,
  );
}

main();
